(p/'conservation'/'index.html').write_text(doc('Conservation',conservation))
collabs=lead('PROJECTS / COLLABORATIONS','Made with purpose.','Selected work across film, conservation and place-based storytelling. Each credit below is linked to its public source.')+section('SELECTED PARTNERSHIPS','The collaborations.',simple('WWF Mediterranean / COGITO','Rabii joined an international filmmaking team for Blue Future.',S['blue'],'DOCUMENTARY')+simple('YKONE Tunis / Land Rover Defender','Rabii featured in a visual road trip through Tunisia’s landscapes for the Defender launch.',S['defender'],'CAMPAIGN')+simple('Zakher Bouragaoui / Tunisian Wonders','Wildlife Wonders was produced with ecologist Zakher Bouragaoui; project support is described in Rabii’s published credit.',S['wildlife'],'WILDLIFE FILM')+simple('Jninet El Hafsia','The community garden hosted a public screening of Wildlife Wonders.',S['screening'],'SCREENING'))
collabs+=reel('Blue Future','OyaSu8oF-D8','WWF / COGITO',S['blue'])+media_pair(visual(0,'Tunisia','Aïn Draham · editorial image'),visual(1,'Across the land','Sahara · editorial image'))
(p/'collaborations'/'index.html').write_text(doc('Collaborations',collabs))
about=lead('ABOUT / RABII BEN BRAHIM','The Dreamer behind the lens.','A Tunisian filmmaker and explorer following the threads between nature, culture and the lives of people who belong to a place.')+f'<figure class="feature-image press-image"><img src="https://www.arabnews.fr/sites/default/files/styles/670x395/public/2022-01/1%20image0%20%283%29_0.jpeg?h=7262c4fb" alt="Rabii Ben Brahim pictured in Arab News"><figcaption>RABII BEN BRAHIM · <a href="{S['story']}" target="_blank" rel="noopener">PHOTO: ARAB NEWS EN FRANÇAIS ↗</a></figcaption></figure>'+section('THE BEGINNING','Curiosity became a journey.','<p class="research-paragraph">Rabii’s father introduced him to documentaries and encouraged his questions about the world. An uncle living close to the forest in northwestern Tunisia shaped his understanding of the relationship between people and nature. Rabii began exploring and sharing little-known places in Tunisia with a camera and backpack.</p>'+ext(S['story'],'Read Rabii’s interview'))+section('THE VISION','See a place. Understand its people.','<p class="research-paragraph">In an interview, Rabii described his mission as helping preserve Tunisia’s natural and cultural heritage. His stories move between mountains, forests, desert and coast, giving space to people whose knowledge and livelihoods are connected to those environments.</p>'+ext(S['tourism'],'Early journey'))
about+=media_pair(visual(0,'The forest','Northwestern Tunisia · editorial image'),visual(1,'The desert','Southern Tunisia · editorial image'))
(p/'about'/'index.html').write_text(doc('About',about))
speaking=lead('SPEAKING / MEDIA','A story beyond the screen.','Conversations about nature, film and what it means to see one’s own country with fresh eyes.')+section('SELECTED APPEARANCES','On stage and in conversation.',simple('TEDxDjerba — What I can do in Tunisia','Rabii spoke at TEDxDjerba in December 2017.',S['ted'],'TALK / 2017')+simple('Arab News en français — The Dreamer','An interview about his childhood, environmental mission and Mediterranean film work.',S['story'],'INTERVIEW / 2022')+simple('Wildlife Wonders — Jninet El Hafsia','An open-air screening of the documentary at the Tunis community garden.',S['screening'],'SCREENING / 2025'))
speaking+=media_pair(visual(0,'A journey begins','Aïn Draham · editorial image'),visual(2,'A place to protect','Ichkeul · editorial image'))
(p/'speaking'/'index.html').write_text(doc('Speaking & Media',speaking))
prints=lead('FINE ART PRINTS','Bring the story home.','A considered selection of photographs may become available as fine art prints.')+section('FUTURE COLLECTION','Selected by the artist.','<p class="research-paragraph">The print collection is in preparation. Editions, formats, prices and shipping details will be announced only when Rabii confirms the selected images and production details.</p>'+ext(IG,'Explore original photographs'))
